import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Form = {
  ORDEN: string;
  EMPRESA: string;
  SERVIC: string;
  TIPCTA: string;
  CUENTA: string;
  VALOR: string;
  CANAL: string;
  CLAVE: string;
};

type Errors = Partial<Record<keyof Form, string>>;

const EMPTY: Form = {
  ORDEN: '',
  EMPRESA: '',
  SERVIC: '',
  TIPCTA: '',
  CUENTA: '',
  VALOR: '',
  CANAL: 'WEB', // initial value of the legacy field
  CLAVE: '',
};

const SAMPLE: Form = {
  ORDEN: '1048213',
  EMPRESA: '00452',
  SERVIC: 'ENERGIA',
  TIPCTA: 'AHO',
  CUENTA: '0012345678',
  VALOR: '185400.50',
  CANAL: 'WEB',
  CLAVE: '482915',
};

const digits = (v: string, max: number) => v.replace(/\D/g, '').slice(0, max);

type Message = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null;

export default function PagoOrdenes({ navigate }: { navigate: (to: string) => void }) {
  const [form, setForm] = useState<Form>(EMPTY);
  const [errors, setErrors] = useState<Errors>({});
  const [message, setMessage] = useState<Message>(null);
  const [paid, setPaid] = useState(false);

  const set = (key: keyof Form, value: string) => {
    setForm((f) => ({ ...f, [key]: value }));
    if (errors[key]) setErrors((e) => ({ ...e, [key]: undefined }));
    if (paid) setPaid(false);
  };

  const validate = (): Errors => {
    const e: Errors = {};
    if (!form.ORDEN) e.ORDEN = 'El número de orden es obligatorio.';
    if (!form.EMPRESA) e.EMPRESA = 'La empresa es obligatoria.';
    if (form.CUENTA && !/^\d{1,10}$/.test(form.CUENTA)) e.CUENTA = 'La cuenta debe ser numérica (hasta 10 dígitos).';
    if (form.VALOR && !/^\d{1,9}(\.\d{1,2})?$/.test(form.VALOR))
      e.VALOR = 'Valor inválido: hasta 9 enteros y 2 decimales.';
    if (form.CANAL && form.CANAL !== 'WEB' && form.CANAL !== 'OFI') e.CANAL = 'El canal debe ser WEB u OFI.';
    return e;
  };

  const pay = () => {
    const e = validate();
    setErrors(e);
    if (Object.keys(e).length > 0) {
      setPaid(false);
      setMessage({ tone: 'error', text: 'Revise los campos marcados antes de pagar.' });
      return;
    }
    setPaid(true);
    setMessage({ tone: 'success', text: `Pago de la orden ${form.ORDEN} enviado para procesamiento.` });
  };

  const cancel = () => {
    setForm(EMPTY);
    setErrors({});
    setPaid(false);
    setMessage({ tone: 'info', text: 'Operación cancelada. Los datos fueron limpiados.' });
  };

  const back = () => navigate('SCR-PAGOMEN');

  const onKeyDown = (ev: React.KeyboardEvent<HTMLDivElement>) => {
    if (ev.key === 'F3') {
      ev.preventDefault();
      back();
    } else if (ev.key === 'F12') {
      ev.preventDefault();
      cancel();
    } else if (ev.key === 'Enter' && (ev.target as HTMLElement).tagName === 'INPUT') {
      ev.preventDefault();
      pay();
    }
  };

  return (
    <div onKeyDown={onKeyDown}>
      <Screen
        title="Pago de órdenes"
        code="SCR-PAGOORD"
        keys={
          <KeyBar
            actions={[
              { key: 'ENTER', label: 'Pagar', onPress: pay, primary: true },
              { key: 'PF3', label: 'Volver', onPress: back },
              { key: 'PF12', label: 'Cancelar', onPress: cancel },
            ]}
          />
        }
      >
        <Stack>
          <div data-field="MENSAJE" role="status" aria-live="polite" style={{ minHeight: 48 }}>
            {message && <Alert tone={message.tone}>{message.text}</Alert>}
          </div>

          <Grid columns={2}>
            <Card title="Datos de la orden">
              <Stack>
                <div data-field="ORDEN">
                  <TextField
                    label="Número de orden"
                    required
                    numeric
                    maxLength={7}
                    hint="Hasta 7 dígitos"
                    error={errors.ORDEN}
                    value={form.ORDEN}
                    onChange={(v: string) => set('ORDEN', digits(v, 7))}
                  />
                </div>
                <div data-field="EMPRESA">
                  <TextField
                    label="Empresa"
                    required
                    numeric
                    maxLength={5}
                    hint="Hasta 5 dígitos"
                    error={errors.EMPRESA}
                    value={form.EMPRESA}
                    onChange={(v: string) => set('EMPRESA', digits(v, 5))}
                  />
                </div>
                <div data-field="SERVIC">
                  <TextField
                    label="Servicio"
                    maxLength={10}
                    hint="Máximo 10 caracteres"
                    error={errors.SERVIC}
                    value={form.SERVIC}
                    onChange={(v: string) => set('SERVIC', v.toUpperCase().slice(0, 10))}
                  />
                </div>
              </Stack>
            </Card>

            <Card title="Cuenta y valor">
              <Stack>
                <div data-field="TIPCTA">
                  <TextField
                    label="Tipo de cuenta"
                    maxLength={3}
                    hint="3 caracteres, por ejemplo AHO o CTE"
                    error={errors.TIPCTA}
                    value={form.TIPCTA}
                    onChange={(v: string) => set('TIPCTA', v.toUpperCase().slice(0, 3))}
                  />
                </div>
                <div data-field="CUENTA">
                  <TextField
                    label="Cuenta"
                    numeric
                    maxLength={10}
                    hint="Hasta 10 dígitos"
                    error={errors.CUENTA}
                    value={form.CUENTA}
                    onChange={(v: string) => set('CUENTA', digits(v, 10))}
                  />
                </div>
                <div data-field="VALOR">
                  <TextField
                    label="Valor"
                    numeric
                    maxLength={12}
                    hint="Hasta 9 enteros y 2 decimales, por ejemplo 185400.50"
                    error={errors.VALOR}
                    value={form.VALOR}
                    onChange={(v: string) => set('VALOR', v.replace(/[^\d.]/g, '').slice(0, 12))}
                  />
                </div>
              </Stack>
            </Card>
          </Grid>

          <Card title="Canal y aprobación">
            <Grid columns={2}>
              <div data-field="CANAL">
                <SelectField
                  label="Canal (WEB/OFI)"
                  options={[
                    { value: 'WEB', label: 'WEB' },
                    { value: 'OFI', label: 'OFI' },
                  ]}
                  hint="Valor inicial: WEB"
                  error={errors.CANAL}
                  value={form.CANAL}
                  onChange={(v: string) => set('CANAL', v)}
                />
              </div>
              <div data-field="CLAVE">
                <label htmlFor="clave-aprobacion" style={{ display: 'block', fontWeight: 600, marginBottom: 4 }}>
                  Clave de aprobación
                </label>
                <input
                  id="clave-aprobacion"
                  type="password"
                  autoComplete="off"
                  maxLength={6}
                  value={form.CLAVE}
                  onChange={(ev) => set('CLAVE', ev.target.value.slice(0, 6))}
                  aria-describedby="clave-hint"
                  style={{ width: '100%', padding: 8, boxSizing: 'border-box' }}
                />
                <div id="clave-hint" style={{ fontSize: 12, opacity: 0.75, marginTop: 4 }}>
                  Hasta 6 caracteres. Se oculta al digitarla, como en la pantalla original.
                </div>
              </div>
            </Grid>
          </Card>

          <Row>
            <Button variant="primary" shortcut="ENTER" onClick={pay}>
              Pagar
            </Button>
            <Button variant="secondary" shortcut="PF12" onClick={cancel}>
              Cancelar
            </Button>
            <Button variant="ghost" shortcut="PF3" onClick={back}>
              Volver
            </Button>
            <Button
              variant="ghost"
              onClick={() => {
                setForm(SAMPLE);
                setErrors({});
                setPaid(false);
                setMessage({ tone: 'info', text: 'Datos de ejemplo cargados para la revisión.' });
              }}
            >
              Cargar datos de ejemplo
            </Button>
            {paid && (
              <Button variant="primary" onClick={() => navigate('SCR-PAGORES')}>
                Ver resultado del pago
              </Button>
            )}
          </Row>

          <div style={{ fontSize: 12, opacity: 0.75 }}>Los campos con * son obligatorios.</div>
        </Stack>
      </Screen>
    </div>
  );
}
